#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <queue>
#include <algorithm>
#include <string>

using namespace std;

class InputReader {
private:
    ifstream stream;
    char buf[8192];
    int curChar, snumChars;

public:
    InputReader(const char* filename) {
        stream.open(filename);
    }

    int read() {
        if (snumChars == -1)
            throw runtime_error("InputMismatchException");
        if (curChar >= snumChars) {
            curChar = 0;
            try {
                snumChars = stream.read(buf, 8192);
            } catch (ifstream::failure& e) {
                throw runtime_error("InputMismatchException");
            }
            if (snumChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    int nextInt() {
        int c = read();
        while (isspace(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isspace(c));
        return res * sgn;
    }

    long nextLong() {
        int c = read();
        while (isspace(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isspace(c));
        return res * sgn;
    }

    int* nextIntArray(int n) {
        int* a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    string readString() {
        int c = read();
        while (isspace(c)) {
            c = read();
        }
        stringstream ss;
        do {
            ss << c;
            c = read();
        } while (!isspace(c));
        return ss.str();
    }

    string nextLine() {
        int c = read();
        while (isspace(c))
            c = read();
        stringstream ss;
        do {
            ss << c;
            c = read();
        } while (!isEndOfLine(c));
        return ss.str();
    }

    bool isSpaceChar(int c) {
        return isspace(c) || c == -1;
    }

    bool isEndOfLine(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }
};

int main() {
    InputReader in("input.txt");
    int n = in.nextInt();
    int b = in.nextInt();
    int* a = in.nextIntArray(n);
    int odd[n + 1];
    int even[n + 1];
    odd[0] = 0;
    even[0] = 0;
    for (int i = 1; i <= n; i++) {
        if (a[i - 1] % 2 == 1) {
            odd[i] = odd[i - 1] + 1;
            even[i] = even[i - 1];
        }
        else {
            odd[i] = odd[i - 1];
            even[i] = even[i - 1] + 1;
        }
    }
    int prev = 0;
    priority_queue<int> cost;
    for (int i = 1; i <= n - 1; i++) {
        int oc = odd[i] - odd[prev];
        int ec = even[i] - even[prev];
        if (oc == ec) {
            cost.push(abs(a[i] - a[i - 1]));
            prev = i;
