                buckets[diff]++;
                sum += diff;
            } else if (sum < B){
                sum += diff;
                buckets[diff]++;
                count++;
                start = i + 1;
            }
            if (i == n - 2 && k < n - 1) {
                i = start++;
                evens = odds = 0;
            }
        }

    }
    int i = buckets.size() - 1;
    while (sum > B) {
        if (buckets[i] > 0) {
            sum -= i;
            count--;
        } else {
            i--;
        }
    }

    cout << count << endl;
    return 0;
}

int bucketMax(vector<int>& buckets) {
    for (int i = buckets.size() - 1; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

