#include <algorithm>

using namespace std;

vector<int> strToIntArr(string s) {
    string sArr[1000];
    int len = 0;
    istringstream iss(s);
    string token;
    while (iss >> token) {
        sArr[len++] = token;
    }
    vector<int> retArr(len);
    for (int i = 0; i < len; i++) {
        retArr[i] = stoi(sArr[i]);
    }
    return retArr;
}

bool checkSub(vector<int>& aArr, int splitInd) {
    bool correct = true;
    int nEven = 0;
    int nOdd = 0;
    for (int i = 0; i <= splitInd; i++) {
        int el = aArr[i];
        if ((el % 2) == 0) {
            nEven++;
        } else {
            nOdd++;
        }
    }
    if (nEven != nOdd) {
        correct = false;
    }
    return correct;
}

int getMinAvailInd(vector<int>& aArr, int nCoins, unordered_map<int, bool>& cutUsed) {
    int len = aArr.size();
    int minInd = -1;
    int minCost = nCoins + 1;
    // between 2 els
    for (int i = 1; i < (len - 1); i++) {
        int cost = abs(aArr[i] - aArr[i + 1]);
        if (cost < minCost) {
            if (checkSub(aArr, i)) {
                if (cutUsed.find(i) == cutUsed.end()) {
                    minCost = cost;
                    minInd = i;
                }
            }
        }
    }
    return minInd;
}

int getMaxCuts(int n, int b, vector<int>& aArr) {
    int nCoins = b;
    int nCuts = 0;
    unordered_map<int, bool> cutUsed;
    while (nCoins > 0) {
        int ind = getMinAvailInd(aArr, nCoins, cutUsed);
        // System.out.format("found ind %d\n",ind);
        if (ind > -1) {
            cutUsed[ind] = true;
            int cost = abs(aArr[ind] - aArr[ind + 1]);
            nCoins -= cost;
            nCuts++;
        } else {
            break;
        }
    }
    return nCuts;
}

