    string nbLn, aLn;
    getline(cin, nbLn);
    getline(cin, aLn);
    vector<int> nbArr = strToIntArr(nbLn);
    vector<int> aArr = strToIntArr(aLn);
    int n = nbArr[0];
    int b = nbArr[1];
    int maxC = getMaxCuts(n, b, aArr);
    cout << maxC << endl;
    return 0;
}

