        }
        if ((mask & 1) == 1) {
            return answer[row][col][mask] = go(row, col + 1, mask >> 1);
        }
        answer[row][col][mask] = go(row, col + 1, mask >> 1);
        answer[row][col][mask] =
                max(go(row, col + 1, (mask >> 1) + (1LL << (3LL * n - 1))) + 2, answer[row][col][mask]);
        if (col != 0 && (mask >> (2LL * n - 1) & 1) == 0) {
            answer[row][col][mask] = max(answer[row][col][mask], go(row, col + 1,
                    (mask >> 1) + (1LL << (2LL * n - 2))) + 2);
        }
        if (col != n - 1 && (mask >> (2LL * n + 1) & 1) == 0) {
            answer[row][col][mask] = max(answer[row][col][mask], go(row, col + 1,
                    (mask >> 1) + (1LL << (2LL * n))) + 2);
        }
        if (col >= 2 && (mask >> (n - 2) & 1) == 0) {
            answer[row][col][mask] = max(answer[row][col][mask], go(row, col + 1,
                    (mask >> 1) + (1LL << (n - 3))) + 2);
        }
        if (col < n - 1 && (mask >> (n + 2) & 1) == 0) {
            answer[row][col][mask] = max(answer[row][col][mask], go(row, col + 1,
                    (mask >> 1) + (1LL << (n + 1))) + 2);
