const long long mod = 1e9 + 7;

long long pow(long long a, long long N) {
    if (N == 0) return 1;
    else if (N == 1) return a;
    else {
        long long R = pow(a, N / 2);
        if (N % 2 == 0) {
            return R * R;
        }
        else {
            return R * R * a;
        }
    }
}

long long powMod(long long a, long long N) {
    if (N == 0) return 1;
    else if (N == 1) return a % mod;
    else {
        long long R = powMod(a, N / 2) % mod;
        R *= R % mod;
        if (N % 2 == 1) {
            R *= a % mod;
        }
        return R % mod;
    }
}

void mergeSort(vector<int>& A) { // low to hi sort, single array only
    int n = A.size();
    if (n < 2) return;
    vector<int> l(n / 2);
    vector<int> r(n - n / 2);

    for (int i = 0; i < n / 2; i++) {
        l[i] = A[i];
    }

    for (int j = n / 2; j < n; j++) {
        r[j - n / 2] = A[j];
    }

    mergeSort(l);
    mergeSort(r);
    merge(l, r, A);
}

void merge(vector<int>& l, vector<int>& r, vector<int>& a) {
    int i = 0, j = 0, k = 0;
    while (i < l.size() && j < r.size() && k < a.size()) {
        if (l[i] < r[j]) {
            a[k] = l[i];
