    if(n % 2 == 1 && m % 2 == 1) res--;

    if(n == 1){
        long x = ((n*m)/6)*6;
        long y = (n*m) % 6;
        if(y == 4) x += 2;
        if(y == 5) x += 4;
        return x;
    }
    if(n == 2 && m == 2) return 0;
    if(n == 2 && m == 3) return 4;
    if(n == 2 && m == 7) return 12;

    return res;
}

