        }

        void addEdge(int[][] mat, List[] g, int i, int j, int s, int t) {
            if (s <= 0 || t <= 0 || s > n || t > m)
                return;

            g[mat[i][j]].add(mat[s][t]);
        }

        class HopcroftKarpBipartiteMatching {
            int m;
            int n;
            List[] g;
            int[] pairU;
            int[] pairV;
            int[] dis;
            int inf = 10000000;
            int NIL = 0;

            public HopcroftKarpBipartiteMatching(int m, int n, List[] g) {
                this.m = m;
                this.n = n;
                this.g = g;
                this.pairU = new int[m + 1];
                this.pairV = new int[n + 1];
                this.dis = new int[m + 1];
            }

            int maximumMatching() {

                Arrays.fill(pairU, NIL);
                Arrays.fill(pairV, NIL);

                int maxMatching = 0;

                while (bfs()) {
                    for (int i = 1; i <= m; i++) {
                        if (pairU[i] == NIL && dfs(i))
                            maxMatching++;
                    }
                }

                return maxMatching;
            }

            boolean bfs() {

                ArrayDeque<Integer> queue = new ArrayDeque<>();

                for (int i = 1; i <= m; i++) {
                    if (pairU[i] == NIL) {
                        queue.addLast(i);
                        dis[i] = 0;
                    } else {
                        dis[i] = inf;
                    }
                }

                dis[NIL] = inf;

                while (!queue.isEmpty()) {
                    int u = queue.removeFirst();

                    if (dis[u] < dis[NIL]) {
                        for (int v : (List<Integer>) g[u]) {
                            if (dis[pairV[v]] == inf) {
                                queue.addLast(pairV[v]);
                                dis[pairV[v]] = dis[u] + 2;
                            }
                        }
                    }
                }

                return dis[NIL] < inf;
            }

            boolean dfs(int u) {
                if (u != NIL) {
                    for (int v : (List<Integer>) g[u]) {
                        if (dis[pairV[v]] == dis[u] + 2) {
                            if (dfs(pairV[v])) {
                                pairV[v] = u;
                                pairU[u] = v;
                                return true;
                            }
                        }
                    }
                    dis[u] = inf;
                    return false;
                } else
                    return true;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void println(long i) {
            writer.println(i);
        }

    }
}

