        bufi = 0;
    }

    bool pumpBuf() {
        if (bufi == bufc) {
            fillBuf();
        }
        return bufc != 0;
    }

    bool isDelimiter(char c) {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
    }

    void eatDelimiters() {
        while (true) {
            if (bufi == bufc) {
                fillBuf();
                if (bufc == 0) {
                    throw runtime_error("IO: Out of input.");
                }
            }

            if (!isDelimiter(buf[bufi])) {
                break;
            }
            ++bufi;
        }
    }

    string next() {
        stringstream ss;
        eatDelimiters();
        int start = bufi;

        while (true) {
            if (bufi == bufc) {
                ss << buf, start, bufi - start;
                fillBuf();
                start = 0;
                if (bufc == 0) {
                    break;
                }
            }

            if (isDelimiter(buf[bufi])) {
                break;
            }
            ++bufi;
        }

        ss << buf, start, bufi - start;
        return ss.str();
    }

    int nextInt() {
        int ret = 0;
        eatDelimiters();

        bool positive = true;
        if (buf[bufi] == '-') {
            ++bufi;
            if (!pumpBuf()) {
                throw runtime_error("IO.nextInt: Invalid int.");
            }
            positive = false;
        }

        bool first = true;
        while (true) {
            if (!pumpBuf()) {
                break;
            }
            if (isDelimiter(buf[bufi])) {
                if (first) {
                    throw runtime_error("IO.nextInt: Invalid int.");
                }
                break;
            }
            first = false;

            if (buf[bufi] >= '0' && buf[bufi] <= '9') {
                if (ret < -214748364) {
                    throw runtime_error("IO.nextInt: Invalid int.");
                }
                ret *= 10;
                ret -= (int)(buf[bufi] - '0');
                if (ret > 0) {
                    throw runtime_error("IO.nextInt: Invalid int.");
                }
            } else {
                throw runtime_error("IO.nextInt: Invalid int.");
            }

            ++bufi;
        }

        if (positive) {
            if (ret == -2147483648) {
                throw runtime_error("IO.nextInt: Invalid int.");
            }
            ret = -ret;
        }

        return ret;
    }

    long nextLong() {
        long ret = 0;
        eatDelimiters();

        bool positive = true;
        if (buf[bufi] == '-') {
            ++bufi;
            if (!pumpBuf()) {
                throw runtime_error("IO.nextLong: Invalid long.");
            }
            positive = false;
        }

        bool first = true;
        while (true) {
            if (!pumpBuf()) {
                break;
            }
            if (isDelimiter(buf[bufi])) {
                if (first) {
                    throw runtime_error("IO.nextLong: Invalid long.");
                }
                break;
            }
            first = false;

            if (buf[bufi] >= '0' && buf[bufi] <= '9') {
                if (ret < -922337203685477580L) {
                    throw runtime_error("IO.nextLong: Invalid long.");
                }
                ret *= 10;
                ret -= (long)(buf[bufi] - '0');
                if (ret > 0) {
                    throw runtime_error("IO.nextLong: Invalid long.");
                }
            } else {
                throw runtime_error("IO.nextLong: Invalid long.");
            }

            ++bufi;
        }

        if (positive) {
            if (ret == -9223372036854775808L) {
                throw runtime_error("IO.nextLong: Invalid long.");
            }
            ret = -ret;
        }

        return ret;
    }

    double nextDouble() {
        return stod(next());
    }

    void println(int output) {
        cout << output << endl;
    }

    void println(long output) {
        cout << output << endl;
    }

    void println(double output) {
        cout << output << endl;
    }

    void println(string output) {
        cout << output << endl;
    }

    void close() {
        cout.flush();
    }
};

class Solver {
public:
    IO io;

    Solver() {
        this->io = IO();
        try {
            solve();
        } catch (runtime_error& e) {
            if (e.what() != "Clean exit") {
                throw;
            }
        } finally {
            io.close();
        }
    }

    void solve() {
        long n = io.nextLong();
        long m = io.nextLong();
        if (m < n) {
            long helper = m;
            m = n;
            n = helper;
        }

        if (n == 1) {
            io.println(brute1(m));
            return;
        }
        if (n == 2) {
            if (m < 3) io.println(0);
            else if (m == 3) io.println(4);
            else if (m == 7) io.println(12);
            else io.println(2 * m);
            return;
        }

        io.println(2 * (n * m / 2)); // jos pariton maara ruutuja ni ei voi laittaa vikaa millaan
        // muuten vaikuttaisi että voi aina laittaa kaikkiin ruutuihin
    }

    long brute1(long m) {
        long ans = 6 * (m / 6);
        if (m % 6 == 5) ans += 4;
        else if (m % 6 == 4) ans += 2;
        return ans;
    }
};

int main() {
    Solver solver;
    return 0;
}

