    void print(int i) {
        outputStream << i;
    }

private:
    ostream &outputStream;
};

class MathUtility {
public:
    static int add(int a, int b, int MOD) {
        int res = a + b;
        if (res >= MOD) {
            res -= MOD;
        }
        return res;
    }
};

class InputReader {
public:
    InputReader(istream &stream) : stream(stream) {}

    int read() {
        if (numChars == -1) {
            throw runtime_error("InputMismatchException");
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf, 1024);
            } catch (exception &e) {
                throw runtime_error("InputMismatchException");
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    int nextInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') {
                throw runtime_error("InputMismatchException");
            }
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    bool isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

private:
    istream &stream;
    char buf[1024];
    int curChar = 0;
    int numChars = 0;
};

class DNekoAndAkisPrank {
public:
    static const int MOD = 1000000007;

    void solve(int testNumber, InputReader &in, OutputWriter &out) {
        int n = in.nextInt();
        out.print(solve(n));
    }

    int solve(int n) {
        int N = 2 * n;
        vector<vector<vector<int>>> dp(N + 1, vector<vector<int>>(N + 1, vector<int>(2)));
        dp[0][0][0] = 0;
        dp[0][0][1] = 0;
        for (int i = 1; i <= N; i++) {
            for (int j = 0; j <= i; j++) {
                for (int k = 0; k <= 1; k++) {
                    dp[i][j][k] = 0;
                    if (k == 1) {
                        if (i - j >= 2) {
                            dp[i][j][k] = MathUtility::add(dp[i][j][k], dp[i - 1][j + 1][0], MOD);
                        }
                        if (j > 0) {
                            dp[i][j][k] = MathUtility::add(dp[i][j][k], dp[i - 1][j - 1][0], MOD);
                        }
                    } else {
                        dp[i][j][k] = max(getVal(dp, i, j, false, false),
                                max(getVal(dp, i, j, false, true),
                                        getVal(dp, i, j, true, false)));
                    }
                }
            }
        }
        return dp[N][0][0];
    }

    int getVal(vector<vector<vector<int>>> &dp, int i, int j, bool selectStart, bool selectEnd) {
        int ret = 0;
        if (i - j >= 2) {
            if (selectStart) {
                ret = MathUtility::add(ret, dp[i - 1][j + 1][1], MOD);
                ret = MathUtility::add(ret, 1, MOD);
            } else {
                ret = MathUtility::add(ret, dp[i - 1][j + 1][0], MOD);
            }
        }
        if (j > 0) {
            if (selectEnd) {
                ret = MathUtility::add(ret, dp[i - 1][j - 1][1], MOD);
                ret = MathUtility::add(ret, 1, MOD);
            } else {
                ret = MathUtility::add(ret, dp[i - 1][j - 1][0], MOD);
            }
        }
        return ret;
    }

};

int main() {
    InputReader in(cin);
    OutputWriter out(cout);
    DNekoAndAkisPrank solver;
    solver.solve(1, in, out);
    out.close();
    return 0;
}

