                int m = max(dp1[x][y+1], dp2[x][y+1]);
                d1 = max(d1, 1+d2-m + dp2[x][y+1]);
                d1 %= MOD;
                if (d1 < 0) d1 += MOD;
            }
            d1 %= MOD;
            if (d1 < 0) d1 += MOD;
            d2 %= MOD;
            if (d2 < 0) d2 += MOD;

            dp1[x][y] = d1;
            dp2[x][y] = d2;
        }

    int ans = max(dp1[0][0], dp2[0][0]);

    cout << ans << endl;

    return 0;
