long modexp(long a, long power, int mod) {
    if (power == 0) {
        return 1;
    }
    if (power == 1) {
        return a;
    }
    long small = modexp(a, power / 2, mod);
    long ans = (small % mod * small % mod) % mod;
    if (power % 2 != 0) {
        ans = (ans % mod + a) % mod;
    }
    return ans;
}

int main() {
    int n, m, l, r;
    long total;
    int mod = 998244353;

    cin >> n >> m >> l >> r;
    total = 1l * n * m;

    if (total % 2 != 0) {
        long ans = modexp(r - l + 1, total, mod);
        cout << ans << endl;
    } else {
        int k = r - l + 1;
        int e = r / 2 - l / 2;
        if (l % 2 == 0) {
            e++;
        }
        int o = k - e;

        long ans = modexp(e + o, total, mod);
        ans = (ans + modexp(e - o, total, mod)) % mod;
        ans = (ans * modexp(2, mod - 2, mod)) % mod;
        cout << ans << endl;
    }

    return 0;
}

