		char a = '(';
		char b = ')';
		int last = -1;
		for(int i = 0; i < s.length(); i ++){
			char c = s.charAt(i);
			if(c == a){
				last = i;
			}
			if(c == b && last != -1){
				li.add(s.substring(last+1, i));
			}
		}
		int count = 0;
		for(int i = 0; i < li.size(); i++){
			String[] words = li.get(i).split("_");
			for(int j = 0; j < words.length; j++){
				if(words[j].length() > 0) count++;
			}
		}
