    string next() {
        while (st.empty() || !st.hasMoreTokens()) {
            string line;
            getline(file, line);
            if (line.empty()) {
                return "";
            }
            st = stringstream(line);
        }
        return st.nextToken();
    }

    bool hasNext() {
