        vector<string> outSite;
        regex re(pattern);
        sregex_token_iterator it(input.begin(), input.end(), re, -1);
        sregex_token_iterator end;
        for (; it != end; ++it) {
            outSite.push_back(*it);
        }
        int longest = 0;
        for (const auto& s : outSite) {
            longest = max(longest, longestWords(s));
        }
        regex r(pattern);
        sregex_iterator m(input.begin(), input.end(), r);
        sregex_iterator end2;
        long numberInside = 0;
        for (; m != end2; ++m) {
            numberInside += count_if(m->str().begin(), m->str().end(), [](char c){ return c != '(' && c != ')'; }) + 1;
        }
        out << longest << " " << numberInside << endl;
    }

    int longestWords(const string& line) {
        istringstream iss(line);
        vector<string> words;
        string word;
        while (iss >> word) {
            words.push_back(word);
        }
        return *max_element(words.begin(), words.end(), [](const string& a, const string& b){ return a.length() < b.length(); }, [](const string& a, const string& b){ return a.length() > b.length(); });
    }

    string trimParentheses(const string& input) {
        return input.substr(1, input.size() - 2);
    }

};

class InputReader {
public:
    InputReader(istream& inputStream) : reader(inputStream) {}

    int nextInt() {
        string line;
        getline(reader, line);
        istringstream iss(line);
        int num;
        iss >> num;
        return num;
    }

    string next() {
        string line;
        getline(reader, line);
        return line;
    }

private:
    istream& reader;
};

