    std::string newString;
    for (std::sregex_iterator i = words_begin; i != words_end; ++i) {
        std::smatch match = *i;
        newString += match.str().substr(1, match.str().length() - 2);
    }

    std::istringstream iss(newString);
    std::vector<std::string> left;
    std::string word;
    while (iss >> word) {
        left.push_back(word);
    }

    int maxLength = 0;
    for (const auto& str : left) {
        maxLength = std::max(maxLength, static_cast<int>(str.length()));
    }

    std::cout << maxLength << std::endl;

    int count = 0;
    bool isStart = false;
    int startIndex = -1;
    int endIndex = -1;
    for (size_t i = 0; i < s.length(); ++i) {
        char c = s[i];
        if (c == '(') {
            isStart = true;
            startIndex = i;
            continue;
        }
        if (isStart) {
            if (c == ')') {
                isStart = false;
                endIndex = i;
                std::string tmp = s.substr(startIndex + 1, endIndex - startIndex - 1);
                if (tmp.empty())
                    continue;
                if (tmp[0] == '_') {
                    std::istringstream iss(tmp);
                    std::vector<std::string> tmps;
                    std::string word;
