        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            String str = in.nextLine();
            boolean in_par = false, in_word = false;
            int word_cnt = 0, word_len = 0, max_len = 0;

            for (int i = 0; i < n; i++) {
                char c = str.charAt(i);
                if (in_word && (c == '_' || c == '(' || c == ')' || i == n - 1)) {
                    in_word = false;
                    if (!(c == '_' || c == '(' || c == ')')) {
                        word_len++;
                    }
                    if (in_par) {
                        word_cnt++;
                    } else if (word_len > max_len) {
                        max_len = word_len;
                    }
                    if (c == '(') {
                        in_par = true;
                    }
                    if (c == ')') {
                        in_par = false;
                    }
                    word_len = 0;
                } else if (!in_word && !(c == '_' || c == '(' || c == ')')) {
                    in_word = true;
                    word_len++;
                    if (i == n - 1 && word_len > max_len) {
                        max_len = word_len;
                    }
                } else if (in_word) {
                    word_len++;
                } else if (c == '(') {
                    in_par = true;
                } else if (c == ')') {
                    in_par = false;
                }
            }
            out.printf("%d %d", max_len, word_cnt);
        }

    }

    static class FastReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

