ll powm(ll a, ll b, ll m) {
    ll an = 1;
    ll c = a;
    while (b > 0) {
        if (b % 2 == 1)
            an = (an * c) % m;
        c = (c * c) % m;
        b >>= 1;
    }
    return an;
}

ll pathfinder(int fatsleft, int slimsleft, int ridesleft, bool boatpos) {
    if (fatsleft == 0 && slimsleft == 0 && ridesleft == 0)
        return 1;
    if (ridesleft == 0)
        return 0;
