class InputReader {
private:
    istream* stream;
    string line;
    string token;

public:
    InputReader(istream& stream) : stream(&stream), line(), token() {}

    string nextLine() {
        getline(*stream, line);
        return line;
    }

    string next() {
        while (line.empty()) {
            getline(*stream, line);
        }
        size_t pos = line.find(' ');
        if (pos != string::npos) {
            token = line.substr(0, pos);
            line.erase(0, pos + 1);
        } else {
            token = line;
            line.clear();
        }
        return token;
    }

    int nextInt() {
        return stoi(next());
    }

    long nextLong() {
        return stol(next());
    }

    double nextDouble() {
        return stod(next());
    }
};

