        }

        void printLine(double i) {
            *writer << i << endl;
        }

        void printLine(const string& s) {
            *writer << s << endl;
        }

        void close() {
            writer->close();
        }

        void flush() {
            writer->flush();
        }
};

class Task {
    public:
        virtual void solve(int testNumber, InputReader& in, OutputWriter& out) = 0;
};

class A : public Task {
    public:
        void solve(int testNumber, InputReader& in, OutputWriter& out) {
            string str = in.readString();
            int ret = 0, n = str.length(), c = 0;
            for (int i = 1; i < n; i++) {
                if (str[i] != str[i - 1]) {
                    ret += c % 2;
                    c = 0;
                } else
                    c++;
            }
            ret += c % 2;
            out.printLine(ret);
        }
};

class B : public Task {
    public:
        void solve(int testNumber, InputReader& in, OutputWriter& out) {
            string str = in.readString();
            string ret;
            for (int i = 0; i < str.length(); i++) {
                char c = str[i];
                if (c == '>') ret += "1000";
                else if (c == '<') ret += "1001";
                else if (c == '+') ret += "1010";
                else if (c == '-') ret += "1011";
                else if (c == '.') ret += "1100";
                else if (c == ',') ret += "1101";
                else if (c == '[') ret += "1110";
                else ret += "1111";
            }
            int n = 0;
            for (int i = 0; i < ret.length(); i++)
                n = (2 * n + ret[i] - '0') % 1000003;
            out.printLine(n);
        }
};

int main() {
    InputReader in(cin);
    OutputWriter out(cout);
    Task solver = new A();
    solver.solve(1, in, out);
    out.close();
    return 0;
}

