        for (auto i : aa) {
            int m = min(a[i.first], b[i.second]);
            b[i.second] -= m;
            a[i.first] -= m;
        }
        int curr = 0;
        for (int i = 0; i < 3; i++) curr += a[i];
        min = min(min, curr);
