    void per(vector<pair<int, int>> aa, int index, int a[], int b[]) {
        check(aa, a, b);
        for (int i = index; i < aa.size(); i++) {
            swap(aa[i], aa[index]);
            per(aa, index + 1, a, b);
            swap(aa[i], aa[index]);
        }
    }

