public class E {

    private static final FastReader in = new FastReader();
    private static final FastWriter out = new FastWriter();

    public static void main(String[] args) {
        new E().run();
    }

    private void run() {
        var t = 1;
        while (t-- > 0) {
            solve();
        }

        out.flush();
    }

    private void solve() {
        var n = in.nextInt();
        var kt = in.nextLong();

        if (kt >= n) {
            out.println(0);
            return;
        }

        var k = (int) kt;
        var mod = new Modulo(998244353);
        var facts = mod.factorials(n);

        var ans = 0L;
        var c = n - k;
        for (var i = 0; i <= c; i++) {
            var t = mod.times(mod.combination(c, i, facts), mod.pow(c - i, n));
            if (i % 2 == 0) {
                ans = mod.plus(ans, t);
            } else {
                ans = mod.minus(ans, t);
            }
        }
        ans = mod.times(ans, mod.combination(n, n - k, facts));

        if (k > 0) ans = mod.times(ans, 2);
        out.println(ans);
    }

}


