    facts[0] = factInvs[0] = 1;
    for (int i = 1; i < 1000000; i++) facts[i] = (facts[i - 1] * i) % mod;
    factInvs[999999] = pow(facts[999999], mod - 2);
    for (int i = 999998; i >= 0; i--) factInvs[i] = (factInvs[i + 1] * (i + 1)) % mod;
}

long nCk(int n, int k) {
    return (facts[n] * ((factInvs[k] * factInvs[n - k]) % mod)) % mod;
}

long add(long a, long b) {
    return (a + b) % mod;
}

long sub(long a, long b) {
    return ((a - b) % mod + mod) % mod;
}

long mul(long a, long b) {
    return (a * b) % mod;
}

long fastPow(long base, long exp) {
    if (exp == 0) return 1;
    long half = fastPow(base, exp / 2);
    if (exp % 2 == 0) return (half * half) % mod;
    return (half * (half * base)) % mod;
}

long powGo(int base, long exp) {
    long ans = 0;
    for (int sub = 0; sub < base; sub++) {
        long delta = (fastPow(base - sub, exp) * nCk(base, sub)) % mod;
        if (sub % 2 == 0) {
            ans = add(ans, delta);
        } else {
            ans = sub(ans, delta);
        }
    }
    return ans;
}

