		int k = (int)tmp;
		preFact(400000);
		long ans = 0;
		int si = 1;
		long t = cmb(n, n-k);
		for(int i=n-k;i>=1;i--) {
			ans += si * cmb(n-k, i) * pow(i, n);
			ans %= mod;
			if(ans < 0)ans += mod;
			si *= -1;
		}
		ans *= t; ans %= mod;
		if(k!=0)ans *= 2; ans %= mod;
		if(ans < 0) ans += mod;
