    static class TaskC {
        static final int INF = (int) 1e9;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = in.next();
            int nk = 0;
            int nv = 0;
            int no = 0;
            int[] kpos = new int[n];
            int[] vpos = new int[n];
