#include <algorithm>
#include <cstring>
#include <cstdio>

using namespace std;

const int N = 100010;

int cv, ck, cs;
int freq[N][3];
vector<int> pos[3];
int dp[N][N][N][3];

void solve() {
    int n;
    cin >> n;
    string s;
    cin >> s;
    cv = 0;
    ck = 0;
    cs = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j < 3; j++) {
            freq[i][j] = 0;
        }
    }
    for (int i = 0; i < 3; i++) {
        pos[i].clear();
    }
    int idx = 0;
    for (char x : s) {
        for (int j = 0; j < 3; j++) {
            freq[idx][j] = freq[idx + 1][j];
        }
        idx++;
        if (x == 'V') {
            freq[idx][0]++;
            cv++;
            pos[0].push_back(idx);
        } else if (x == 'K') {
            freq[idx][1]++;
            ck++;
            pos[1].push_back(idx);
        } else {
            freq[idx][2]++;
            cs++;
            pos[2].push_back(idx);
        }
    }
    for (int i = 0; i <= cv; i++) {
        for (int j = 0; j <= ck; j++) {
            for (int k = 0; k <= cs; k++) {
                for (int l = 0; l < 3; l++) {
                    dp[i][j][k][l] = -1;
                }
            }
        }
    }
    cout << dfs(0, 0, 0, 2) << endl;
}

int dfs(int tv, int tk, int ts, int last) {
    if (tv == cv && tk == ck && ts == cs) {
        return 0;
    }
    if (dp[tv][tk][ts][last] != -1) return dp[tv][tk][ts][last];
    int ret = 1 << 29;
    if (tv < cv) {
        int p = pos[0][tv];
        int move = max(freq[p][0] - tv, 0) + max(freq[p][1] - tk, 0) + max(freq[p][2] - ts, 0) - 1;
        ret = min(ret, dfs(tv + 1, tk, ts, 0) + move);
    }
    if (tk < ck && last != 0) {
        int p = pos[1][tk];
        int move = max(freq[p][0] - tv, 0) + max(freq[p][1] - tk, 0) + max(freq[p][2] - ts, 0) - 1;
        ret = min(ret, dfs(tv, tk + 1, ts, 1) + move);
    }
    if (ts < cs) {
        int p = pos[2][ts];
        int move = max(freq[p][0] - tv, 0) + max(freq[p][1] - tk, 0) + max(freq[p][2] - ts, 0) - 1;
        ret = min(ret, dfs(tv, tk, ts + 1, 2) + move);
    }
    return dp[tv][tk][ts][last] = ret;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int T = 1;
    while (T--) {
        solve();
    }
    return 0;
}

