    string swap(string s, int i, int j) {
        if (s[i] == s[j]) {
            return "";
        }
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        return s;
    }

    int fast(string s) {
        s = prepare(s);

        int n = s.length();

        vector<int> a(n);
        vector<int> pos[3];
