    std::string next() {
        while (iss.str().empty()) {
            std::getline(in, line);
            iss.clear();
            iss.str(line);
        }
        while (iss >> token) {
            return token;
        }
        return "";
    }

    int nextInt() {
        return std::stoi(next());
    }

    long nextLong() {
        return std::stol(next());
    }

    double nextDouble() {
        return std::stod(next());
    }

    std::string nextLine() {
        std::string str;
        std::getline(in, str);
        return str;
    }
};

