class BIT {
public:
    int tree[MAXN + 5];

    BIT() {
        for (int i = 0; i <= MAXN; i++) {
            tree[i] = 0;
        }
    }

    void update(int index, int val) {
        index++;
        while (index <= MAXN) {
            tree[index] ^= val;
            index += index & -index;
        }
    }

    int query(int index) {
        int result = 0;
        index++;
        while (index > 0) {
            result ^= tree[index];
            index -= index & -index;
        }

        return result;
    }

    int rangeSum(int low, int high) {
        return query(high) - query(low - 1);
    }
};

class BinaryLifting {
public:
    vector<vector<int>> adjList;
    vector<int> tin, tout;
    vector<vector<int>> BL;
    int ct;

    void preprocess(int root) {
        ct = 0;
        tin.resize(adjList.size());
        tout.resize(adjList.size());
        BL.resize(adjList.size(), vector<int>(32));

        recur_bl(root, root);
    }

    void recur_bl(int v, int p) {
        tin[v] = ++ct;
        BL[v][0] = p;
        for (int i = 1; i <= 31; i++) {
            BL[v][i] = BL[BL[v][i - 1]][i - 1];
        }

        for (int i = 0; i < adjList[v].size(); i++) {
            if (adjList[v][i] != p) {
                recur_bl(adjList[v][i], v);
            }
        }

        tout[v] = ++ct;
    }

    bool is_ancestor(int u, int v) {
        return tin[u] <= tin[v] && tout[u] >= tout[v];
    }

    int lca(int u, int v) {
        if (is_ancestor(u, v)) {
            return u;
        }
        if (is_ancestor(v, u)) {
            return v;
        }

        for (int i = 31; i >= 0; i--) {
            if (!is_ancestor(BL[u][i], v)) {
                u = BL[u][i];
            }
        }

        return BL[u][0];
    }
};

