    while (true) {
        if (p % 2 != 0) {
            ans = multiplyMod(ans, v);
        }
        p /= 2;
        if (p == 0) break;
        v = multiplyMod(v, v);
    }
    int res = 0;
    for (int x : ans) {
        res = (res + (long)x * x) % MOD;
    }
    cout << res << '\n';

    return 0;
}

