using namespace std;

#define inf 1e7

class SparseTable {
public:
    int *a;
    int **st;
    SparseTable(int *a) {
        int n = a[0];
        this->a = a;
        int k = (int)floor(log(n) / log(2)) + 1;
        st = new int *[n];
        for (int i = 0; i < n; i++)
            st[i] = new int[k];
        for (int i = 0; i < n; i++)
            st[i][0] = i;
        for (int j = 1; (1 << j) <= n; j++)
            for (int i = 0; i + (1 << (j - 1)) < n; i++)
                if (a[st[i][j - 1]] < a[st[i + (1 << (j - 1))][j - 1]])
                    st[i][j] = st[i][j - 1];
                else
                    st[i][j] = st[i + (1 << (j - 1))][j - 1];
    }
    int query(int i, int j) {
        if (i >= a[0])
            return inf;
        j = min(j, a[0] - 1);
        int k = (int)floor(log(j - i + 1) / log(2));
        return min(a[st[i][k]], a[st[j - (1 << k) + 1][k]]);
    }
};

int main() {
    int n, k;
