        seg[0][1] = new SparseTable(new int[n / 2 + 2]);
        seg[1][0] = new SparseTable(new int[n / 2 + 2]);
        seg[1][1] = new SparseTable(new int[n / 2 + 2]);
        for (int j = 0; j < 2; j++) {
            int *a = new int[n / 2 + 2];
            for (int c = 0; c < n / 2 + 2; c++)
                a[c] = inf;
            a[n / 2] = 0;
            seg[0][j]->a = a;
            seg[1][j]->a = a;
        }
    }
    int p = 0;
    for (int i = k - 1; i >= 0; i--) {
        for (int j = 0; j < 2; j++) {
            int *a = new int[n / 2 + 2];
            for (int c = 0; c < n / 2 + 2; c++)
                a[c] = inf;
            for (int c = 0; c <= l[i] && c < a[0]; c++) {
                int best = seg[1 - p][j]->query(c + l[i + 1] - l[i], c + l[i + 1] - l[i]);
