        return queryUtil(1, 0, size - 1, max(0, l), r);
    }

    int queryUtil(int n, int tl, int tr, int l, int r) {
        //node number, cur range of node, cur range of query
        if (l > r) {
            return MAX;
        }
        if (tl == l && tr == r) {
            return tree[n];
        }
        int tm = (tl + tr) / 2;
        return min(queryUtil(2 * n, tl, tm, l, min(r, tm)), queryUtil(2 * n + 1, tm + 1, tr, max(tm + 1, l), r));
    }

    void assign(int n, int val) {
        arr[n] = val;
        int tl = 0;
        int tr = size - 1;
        int a = 1;
        while (tl < tr) {
            int tm = (tl + tr) >> 1;
            if (n <= tm) {
                tr = tm;
                a = 2 * a;
            } else {
                tl = tm + 1;
                a = 2 * a + 1;
            }
        }
        tree[a] = val;
        a >>= 1;
        while (a > 0) {
            tree[a] = min(tree[2 * a], tree[2 * a + 1]);
            a >>= 1;
        }
    }

    int getVal(int i) {
        if (i < 0) {
            return MAX;
        }
        return arr[i];
    }
};

int main() {
