    vector<pair<int, int>> interval(k);
    for (int i = 0; i < k; i++) {
        cin >> interval[i].first >> interval[i].second;
    }
    interval.push_back(make_pair(2 * N, 2 * N));
    int cur = 0;
    SegmentTree* dp[2]; //how many sides are fried on the front, 0 is currently on front, 1 is currently on back
    dp[0] = new SegmentTree(N + 1);
    dp[1] = new SegmentTree(N + 1);
    dp[0]->assign(0, 0);
    for (int i = 0; i < interval.size(); i++) {
        for (int j = N; j >= 0; j--) {
            dp[0]->assign(j, dp[0]->getVal(j - (interval[i].first - cur)));
        }
        cur = interval[i].second;
        int sz = interval[i].second - interval[i].first;
        for (int j = N; j >= 0; j--) {
            int put[2];
            for (int z = 0; z <= 1; z++) {
                int twoSwaps = dp[z]->query(j - sz, j);
                int oneSwap = dp[(z + 1) % 2]->query(j - sz, j);
                int noSwap;
                if (z == 1) {
                    noSwap = dp[z]->getVal(j);
                } else {
                    noSwap = dp[z]->getVal(j - sz);
                }
                put[z] = min(twoSwaps + 2, min(oneSwap + 1, noSwap));
            }
            dp[0]->assign(j, put[0]);
//            cout << j << " " << put[0] << " " << put[1] << endl;
            dp[1]->assign(j, put[1]);
        }
    }
    int ans = min(dp[0]->query(N, N), dp[1]->query(N, N));
