         int N = input.length();
         int[] arr = new int[N];
         for(int i=0; i < N; i++)
            arr[i] = Integer.parseInt(input.charAt(i)+"");
         //brute force
         pow = new long[16];
         pow[0] = 1L;
         for(int i=1; i <= 15; i++)
            pow[i] = pow[i-1]*10;
         long start = Long.parseLong(input);
         System.out.println(solve(start));
      }
      public static int solve(long x)
      {
         if(x <= 11)
         {
            if(x == 11)
               return 2;
            else if(x == 10)
               return 3;
            else if(x == 9)
               return 4;
            else if(x == 8)
               return 5;
            else if(x == 7)
               return 6;
            else
               return (int)x;
         }
         int len = (x+"").length();
         long boof = 0L;
         for(int i=0; i <= len; i++)
            boof += pow[i];
         int res = Integer.MAX_VALUE;
         if(x > boof-x)
            res = Math.min(res, len+1+solve(boof-x));
         boof -= pow[len];
         for(int d=1; d <= 9; d++)
         {
            boof *= d;
            if(d == x/pow[len-1] || d+1 == x/pow[len-1])//(x > boof-x)
               res = Math.min(res, len*d+solve(Math.abs(boof-x)));
            boof /= d;
         }
         return res;
      }
   }

