    Edge(int a, int b, int c, int d) : u(a), flow(b), cost(c), rid(d) {}
};

class MinCostMaxFlow {
public:
    vector<vector<Edge>> al;
    Edge** ja;
    int d[N], N, S, T, maxFlow, minCost;
    const int gmax = INT_MAX / 100;

    int edges = 0;

    MinCostMaxFlow(int n, int source, int sink) : N(n), S(source), T(sink), maxFlow(0), minCost(0) {
        al.resize(N);
        d = new int[N];
        for (int i = 0; i < N; i++) {
            al[i].clear();
        }
    }

    void addEdge(int u, int v, int flow, int cost) {
        int lu = al[u].size(), lv = al[v].size();
        al[u].push_back(Edge(v, flow, cost, lv));
        al[v].push_back(Edge(u, 0, -cost, lu));
    }

    void convertToArray() {
        ja = new Edge*[N];
        for (int i = 0; i < N; i++) {
            int sz = al[i].size();
            ja[i] = new Edge[sz];
            for (int j = 0; j < sz; j++) {
                ja[i][j] = al[i][j];
            }
            al[i].clear();
        }
    }

    bool BellmanFord(bool check) {
        d[0] = 0;
        for (int i = 0; i < N - 1; i++) {
            for (int j = 0; j < N; j++) {
                for (Edge e : al[j]) {
                    if (e.flow == 0) continue;
                    d[e.u] = min(d[e.u], d[j] + e.cost);
                }
            }
        }
        if (check) {
            for (int j = 0; j < N; j++) {
                for (Edge e : al[j]) {
                    if (e.flow == 0) continue;
                    if (d[j] + e.cost < d[e.u]) return false;
                }
            }
        }
        return true;
    }

    int node[N], visit[N], prv[N], prve[N], dist[N];

    bool simple() {
        node[0] = S; dist[0] = 0;
        int front = 1, back = 0;
        while (front != back) {
            int u = node[back++]; int distu = dist[u];
            if (back == N) back = 0;
            visit[u] = 2;
            for (int i = 0; i < al[u].size(); i++) {
                Edge e = al[u][i];
                if (e.flow == 0) continue;
                int cdist = distu + e.cost;
                if (cdist < dist[e.u]) {
                    if (visit[e.u] == 0) {
                        node[front] = e.u;
                        if (++front == N) front = 0;
                    } else if (visit[e.u] == 2) {
                        if (--back == -1) back += N;
                        node[back] = e.u;
                    }
                    visit[e.u] = 1;
                    prve[e.u] = i; prv[e.u] = u; dist[e.u] = cdist;
                }
            }
        }
        return visit[T] != 0;
    }

    bool dijkstra() {
        visit = new int[N];
        prv = new int[N];
        prve = new int[N];
        dist = new int[N];
        for (int i = 0; i < N; i++) dist[i] = INT_MAX;
        priority_queue<pair, vector<pair>, greater<pair>> pq;
        pq.push(make_pair(S, 0));
        dist[0] = 0;
        while (!pq.empty()) {
            pair p = pq.top();
            pq.pop();
            while (dist[p.first] < p.second) {
                if (pq.empty()) break;
                p = pq.top();
                pq.pop();
            }
            visit[p.first] = 2;
            for (int i = 0; i < al[p.first].size(); i++) {
                Edge e = al[p.first][i];
                if (e.flow == 0) continue;
                int cdist = p.second + (e.cost + d[p.first] - d[e.u]);
                if (cdist < dist[e.u]) {
                    if (visit[e.u] == 2) return false;
                    pq.push(make_pair(e.u, cdist));
                    dist[e.u] = cdist;
                    prv[e.u] = p.first;
                    prve[e.u] = i;
                    visit[e.u] = 1;
                }
            }
        }
        return visit[T] != 0;
    }

    int augment() {
        int p = T;
        int min = INT_MAX;
        while (p != 0) {
            int pp = prv[p], pe = prve[p];
            int val = ja[pp][pe].flow;
            min = min(val, min);
            p = pp;
        }
        p = T;
        while (p != 0) {
            int pp = prv[p], pe = prve[p];
            ja[pp][pe].flow -= min;
            ja[p][ja[pp][pe].rid].flow += min;
            p = pp;
        }
        maxFlow += min;
        return min;
    }

    bool calSimple() {
        while (simple()) {
            minCost += dist[T] * augment();
        }
        return true;
    }

    void updPotential() {
        for (int i = 0; i < N; i++) {
            if (visit[i] != 0) {
                d[i] += dist[i] - dist[S];
            }
        }
    }

    bool calWithPotential() {
        while (dijkstra()) {
            int min = dist[T] + d[T] - d[S];
            minCost += min * augment();
            updPotential();
        }
        return true;
