        private static final int NG = 0;

        public boolean containsKey(long x) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) return true;
                pos = pos + 1 & mask;
            }
            return false;
        }

        public long get(long x) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) return allocated[pos];
                pos = pos + 1 & mask;
            }
            return NG;
        }

        public long put(long x, long v) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    long oldval = allocated[pos];
                    allocated[pos] = v;
                    return oldval;
                }
                pos = pos + 1 & mask;
            }
            if (size == rscale) {
                resizeAndPut(x, v);
            } else {
                keys[pos] = x;
                allocated[pos] = v;
            }
            size++;
            return 0;
        }

        public long inc(long x, long v) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    allocated[pos] += v;
                    return allocated[pos];
                }
                pos = pos + 1 & mask;
            }
            if (size == rscale) {
                resizeAndPut(x, v);
            } else {
                keys[pos] = x;
                allocated[pos] = v;
            }
            size++;
            return v;
        }

        public boolean remove(long x) {
            int pos = h(x) & mask;
            while (allocated[pos] != NG) {
                if (x == keys[pos]) {
                    size--;
