    if (charOccurrencesInEqualPairs[mostCommonCharInEqualPairs] > equalPairs.size() / 2) {
      vector<int> nonEqualPairsMinBeautyPenalties;
      for (int i = 0; i < n / 2; ++i) {
        if (s[i] != s[n - 1 - i] && s[i] != mostCommonCharInEqualPairs && s[n - 1 - i] != mostCommonCharInEqualPairs) {
          nonEqualPairsMinBeautyPenalties.push_back(min(beauty[i], beauty[n - 1 - i]));
        }
      }
      sort(nonEqualPairsMinBeautyPenalties.begin(), nonEqualPairsMinBeautyPenalties.end());
      int rem = 2 * charOccurrencesInEqualPairs[mostCommonCharInEqualPairs] - equalPairs.size();
      for (int i = 0; i < rem; ++i) {
        ans -= nonEqualPairsMinBeautyPenalties[i];
      }
    }

    out << ans << endl;
  }
};

class InputReader {
private:
  FILE* stream;
  char* buf;
  int curChar;
  int numChars;
  bool filter;

public:
  InputReader(FILE* stream) {
    this->stream = stream;
    buf = new char[1024];
    curChar = 0;
    numChars = 0;
    filter = false;
  }

  int read() {
    if (numChars == -1) {
      throw std::runtime_error("End of file");
    }
    if (curChar >= numChars) {
      curChar = 0;
      numChars = fread(buf, 1, 1024, stream);
      if (numChars <= 0) {
        return -1;
      }
    }
    return buf[curChar++];
  }

  int readInt() {
    int c = read();
    while (isSpaceChar(c)) {
      c = read();
    }
    int sgn = 1;
    if (c == '-') {
      sgn = -1;
      c = read();
    }
    int res = 0;
    do {
      if (c < '0' || c > '9') {
        throw std::runtime_error("Invalid integer");
      }
      res *= 10;
      res += c - '0';
      c = read();
    } while (!isSpaceChar(c));
    return res * sgn;
  }

  string readString() {
    int c = read();
    while (isSpaceChar(c)) {
      c = read();
    }
    string res;
    do {
      if (c >= 0 && c <= 127) {
        res += c;
      }
      c = read();
    } while (!isSpaceChar(c));
    return res;
  }

  bool isSpaceChar(int c) {
    if (filter) {
      return filter.isSpaceChar(c);
    }
    return isWhitespace(c);
  }

  bool isWhitespace(int c) {
    return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
  }

  class SpaceCharFilter {
  public:
    virtual bool isSpaceChar(int ch) = 0;
  };
};

int main() {
  FILE* inputStream = stdin;
  FILE* outputStream = stdout;
  InputReader in(inputStream);
  TaskF solver;
  solver.solve(1, in, cout);
  return 0;
}

