class Graph {
private:
    int vNum, src, sink;
    vector<vector<Edge>> graph;
    vector<int> p, d;

public:
    Graph(int vNum, int src, int sink) : vNum(vNum), src(src), sink(sink), graph(vNum), p(vNum), d(vNum) {}

    void addEdge(int from, int to, int capacity, int cost) {
        graph[from].push_back({from, to, capacity, cost});
        graph[to].push_back({to, from, 0, -cost});
    }

    bool findCheapestPath() {
        for (int i = 0; i < vNum; ++i) {
            for (const auto& e : graph[i]) {
                if (e.capacity > 0) {
                    d[e.to] = min(d[e.to], d[e.from] + e.cost);
                    p[e.to] = e.from;
                }
            }
        }
        return p[sink] != -1;
    }

    int augmentPath(int from, int to, int flow) {
        int pathCost = 0;
        for (int cur = to; cur != from; cur = p[cur]) {
            flow = min(flow, graph[p[cur]][cur].capacity);
        }
        for (; to != from; to = p[to]) {
            graph[p[to]][to].capacity -= flow;
            graph[to][p[to]].capacity += flow;
            pathCost += graph[p[to]][to].cost * flow;
        }
        return flow;
    }

    int* getMinCostMaxFlow() {
        int flow = 0;
        int totalCost = 0;
        for (int i = 0; i < vNum - 1; ++i) {
            fill(d.begin(), d.end(), numeric_limits<int>::max());
            fill(p.begin(), p.end(), -1);
            d[src] = 0;
            while (findCheapestPath()) {
                int result = augmentPath(src, sink, numeric_limits<int>::max());
                flow += result;
                totalCost += result;
            }
        }
        return new int[] {flow, totalCost};
    }
};

