    long long modInverse(long long a) {
        long long b = mod;
        long long x = 0, y = 1;

        while (b != 0) {
            long long q = a / b;
            a -= q * b;
            swap(a, b);
            x -= q * y;
            swap(x, y);
        }

        if (x < 0)
            x += mod;

        return x;
