            l -= h * ab;
            r -= h * ab;
            h = (r - l + 1) / ab;
            if (h > 2)
                r -= (h - 2) * ab;
            int d = a > b ? a - b : 1;
            for (h = 0; h < m; h++) {
                for (int k = 0; k < a - d; k++)
                    cc[(a + b) * h + k] = k;
                for (int k = 0; k < d; k++)
