			for (int second = a; second < 26; second++) {
				for (int i = 0; i < b; i++) {
					cString.append((char)('a' + first));
				}
				used.clear();
				for (char c : cString.substring(cString.length() - a, cString.length()).toCharArray()) {
					used.add(c - 'a');
