                    for (int i = 0; i < rep.length(); i++) {
                        flag[rep[i] - 'a'] = true;
                    }
                } else {
                    for (int i = l; i <= r; i++) {
                        flag[rep[i % rep.length()] - 'a'] = true;
                    }
                }

                int ans = 0;
                for (int i = 0; i < 26; i++) if (flag[i]) ans++;
                min = min > ans ? ans : min;
            }
        }
        out << min << endl;
    }
};

class LightScanner {
public:
    LightScanner(istream &in) : in(in) {}

    string string() {
        string str;
        while (!in >> str) {
            in.clear();
            in.ignore(10000, '\n');
        }
        return str;
    }

    int ints() {
        return stoi(string());
    }

private:
    istream &in;
};

class LightWriter {
public:
    LightWriter(ostream &out) : out(out) {}

    LightWriter &print(char c) {
        out.put(c);
        return *this;
    }

    LightWriter &print(const string &s) {
        out << s;
        return *this;
    }

    LightWriter &ans(const string &s) {
        if (out.tellp() > 0 && out.peek() != '\n') print(' ');
        return print(s);
    }

    LightWriter &ans(int i) {
        return ans(to_string(i));
    }

    LightWriter &ln() {
        print('\n');
        out.flush();
        return *this;
    }

private:
    ostream &out;
};

int main() {
    istream &in = cin;
    ostream &out = cout;
    LightScanner inScanner(in);
    LightWriter outWriter(out);
    CMisterBAndBoringGame solver;
    solver.solve(1, inScanner, outWriter);
    outWriter.close();
    return 0;
}

